 46→export const loader = async ({ request }: LoaderFunctionArgs) => {
 47→  const { session } = await authenticate.admin(request);
 48→  const shop = session.shop;
 49→
 50→  const [rules, zones, subscription] = await Promise.all([
 51→    db.deliveryRule.findMany({
 52→      where: { shop },
 53→      orderBy: { priority: "asc" },
 54→    }),
 55→    db.zipCode.findMany({
 56→      where: { shop, zone: { not: null } },
 57→      select: { zone: true },
 58→      distinct: ["zone"],
 59→    }),
 60→    getShopSubscription(shop),
 61→  ]);
 62→
 63→  return {
 64→    rules,
 65→    zones: zones.map((z) => z.zone).filter(Boolean) as string[],
 66→    subscription,
 67→  };
 68→};
 69→
 70→export const action = async ({ request }: ActionFunctionArgs) => {
 71→  const { session } = await authenticate.admin(request);
 72→  const shop = session.shop;
 73→  const formData = await request.formData();
 74→  const intent = formData.get("intent");
 75→
 76→  if (intent === "create" || intent === "update") {
 77→    const id = String(formData.get("id") || "");
 78→    const name = String(formData.get("name") || "").trim();
 79→    const zone = String(formData.get("zone") || "").trim() || null;
 80→    const zipCodes = String(formData.get("zipCodes") || "").trim() || null;
 81→    const minOrderAmount = formData.get("minOrderAmount")
 82→      ? parseFloat(String(formData.get("minOrderAmount")))
 83→      : null;
 84→    const deliveryFee = formData.get("deliveryFee")
 85→      ? parseFloat(String(formData.get("deliveryFee")))
 86→      : null;
 87→    const freeShippingAbove = formData.get("freeShippingAbove")
 88→      ? parseFloat(String(formData.get("freeShippingAbove")))
 89→      : null;
 90→    const estimatedDays =
 91→      String(formData.get("estimatedDays") || "").trim() || null;
 92→    const cutoffTime =
 93→      String(formData.get("cutoffTime") || "").trim() || null;
 94→    const daysOfWeek =
 95→      String(formData.get("daysOfWeek") || "").trim() || null;
 96→    const priority = parseInt(String(formData.get("priority") || "0"), 10);
 97→
 98→    if (!name) return { error: "Rule name is required." };
 99→
100→    const data = {
101→      name,
102→      zone,
103→      zipCodes,
104→      minOrderAmount,
105→      deliveryFee,
106→      freeShippingAbove,
107→      estimatedDays,
108→      cutoffTime,
109→      daysOfWeek,
110→      priority,
111→    };
112→
113→    if (intent === "update" && id) {
114→      await db.deliveryRule.update({ where: { id }, data });
115→      return { success: true, action: "updated" };
116→    } else {
117→      // Plan-gating: check limits before creating a new rule
118→      const subscription = await getShopSubscription(shop);
119→      const { maxDeliveryRules, label: planLabel } = subscription.limits;
120→
121→      if (maxDeliveryRules === 0) {
122→        return {
123→          error:
124→            "Delivery rules are not available on the Free plan. Upgrade to Starter or Pro.",
125→        };
126→      }
127→
128→      if (isFinite(maxDeliveryRules)) {
129→        const currentCount = await db.deliveryRule.count({ where: { shop } });
130→        if (currentCount >= maxDeliveryRules) {
131→          return {
132→            error: `You've reached the ${maxDeliveryRules} delivery rule limit on the ${planLabel} plan. Upgrade to Pro for unlimited rules.`,
133→          };
134→        }
135→      }
136→
137→      await db.deliveryRule.create({ data: { shop, ...data } });
138→      return { success: true, action: "created" };
139→    }
140→  }
141→
142→  if (intent === "delete") {
143→    const id = String(formData.get("id"));
144→    await db.deliveryRule.delete({ where: { id } });
145→    return { success: true, action: "deleted" };
146→  }
147→
148→  if (intent === "toggle") {
149→    const id = String(formData.get("id"));
150→    const isActive = formData.get("isActive") === "true";
151→    await db.deliveryRule.update({
152→      where: { id },
153→      data: { isActive: !isActive },
154→    });
155→    return { success: true, action: "toggled" };
156→  }
157→
158→  return null;
159→};
