 44→export const loader = async ({ request }: LoaderFunctionArgs) => {
 45→  const { session } = await authenticate.admin(request);
 46→  const shop = session.shop;
 47→
 48→  const [entries, subscription] = await Promise.all([
 49→    db.waitlistEntry.findMany({
 50→      where: { shop },
 51→      orderBy: { createdAt: "desc" },
 52→    }),
 53→    getShopSubscription(shop),
 54→  ]);
 55→
 56→  const stats = {
 57→    total: entries.length,
 58→    waiting: entries.filter((e) => e.status === "waiting").length,
 59→    notified: entries.filter((e) => e.status === "notified").length,
 60→    converted: entries.filter((e) => e.status === "converted").length,
 61→    uniqueZips: [...new Set(entries.map((e) => e.zipCode))].length,
 62→  };
 63→
 64→  return { entries, stats, subscription };
 65→};
