 75→    const zipCode = String(formData.get("zipCode") || "")
 76→      .trim()
 77→      .toUpperCase();
 78→    const note = String(formData.get("note") || "").trim() || null;
 79→
 80→    if (!email || !zipCode) return { error: "Email and zip code are required." };
 81→
 82→    const subscription = await getShopSubscription(shop);
 83→    const limits = PLAN_LIMITS[subscription.planTier];
 84→
 85→    if (limits.maxWaitlist === 0) {
 86→      return { error: "Your current plan does not include waitlist access. Upgrade to Starter or higher." };
 87→    }
 88→
 89→    if (isFinite(limits.maxWaitlist)) {
 90→      const currentCount = await db.waitlistEntry.count({ where: { shop } });
 91→      if (currentCount >= limits.maxWaitlist) {
 92→        return { error: `You have reached the ${limits.maxWaitlist}-entry waitlist limit on your ${limits.label} plan. Upgrade to Pro for unlimited entries.` };
 93→      }
 94→    }
 95→
 96→    try {
 97→      await db.waitlistEntry.create({
 98→        data: { shop, email, zipCode, note },
 99→      });
100→      return { success: true, action: "added" };
101→    } catch {
102→      return { error: "This email is already on the waitlist for this zip code." };
103→    }
104→  }
105→
106→  if (intent === "delete") {
107→    const id = String(formData.get("id"));
108→    await db.waitlistEntry.delete({ where: { id } });
109→    return { success: true, action: "deleted" };
110→  }
111→
112→  if (intent === "update-status") {
113→    const id = String(formData.get("id"));
114→    const status = String(formData.get("status"));
115→    await db.waitlistEntry.update({ where: { id }, data: { status } });
116→    return { success: true, action: "updated" };
117→  }
118→
119→  if (intent === "bulk-notify") {
120→    const zipCode = String(formData.get("zipCode") || "")
121→      .trim()
122→      .toUpperCase();
123→    if (!zipCode) return { error: "Zip code is required." };
124→
125→    const bulkNotifySub = await getShopSubscription(shop);
126→    if (isFinite(PLAN_LIMITS[bulkNotifySub.planTier].maxWaitlist)) {
127→      return { error: "Bulk notify is only available on Pro or Ultimate plans. Please upgrade." };
128→    }
129→
130→    const updated = await db.waitlistEntry.updateMany({
131→      where: { shop, zipCode, status: "waiting" },
132→      data: { status: "notified" },
133→    });
134→
135→    return {
136→      success: true,
137→      action: "bulk-notify",
138→      count: updated.count,
139→      zipCode,
140→    };
141→  }
142→
143→  if (intent === "notify-zip") {
144→    const zipCode = String(formData.get("zipCode") || "").trim().toUpperCase();
145→    if (!zipCode) return { error: "No ZIP code specified." };
146→
147→    const notifyZipSub = await getShopSubscription(shop);
148→    if (isFinite(PLAN_LIMITS[notifyZipSub.planTier].maxWaitlist)) {
149→      return { error: "Bulk notify is only available on Pro or Ultimate plans. Please upgrade." };
150→    }
151→
152→    const entries = await db.waitlistEntry.findMany({
153→      where: { shop, zipCode, status: "waiting" },
154→      select: { id: true, email: true },
155→    });
156→
157→    if (entries.length === 0) {
158→      return { action: "notify-zip", zipCode, emails: [] as string[], count: 0 };
159→    }
160→
161→    await db.waitlistEntry.updateMany({
162→      where: { shop, zipCode, status: "waiting" },
163→      data: { status: "notified" },
164→    });
165→
166→    const emails = entries.map((e) => e.email);
167→    return { action: "notify-zip", zipCode, emails, count: emails.length };
168→  }
169→
170→  if (intent === "delete-all-notified") {
171→    const deleted = await db.waitlistEntry.deleteMany({
172→      where: { shop, status: "notified" },
173→    });
174→    return { success: true, action: "deleted-notified", count: deleted.count };
175→  }
176→
177→  return null;
178→};
