15→      db.deliveryRule.deleteMany({ where: { shop } }),
16→      db.waitlistEntry.deleteMany({ where: { shop } }),
17→      db.widgetConfig.deleteMany({ where: { shop } }),
18→      db.subscription.deleteMany({ where: { shop } }),
19→      db.shopSettings.deleteMany({ where: { shop } }),
20→    ]);
21→  }
22→
23→  return new Response();
24→};
